"""Small test-automation suite: a fake checkout service with pytest-style tests
written against the stdlib unittest runner."""
import unittest

class Cart:
    def __init__(self):
        self.items = {}
    def add(self, sku, price, qty=1):
        if qty <= 0 or price < 0:
            raise ValueError("bad qty or price")
        self.items[sku] = (price, self.items.get(sku, (price, 0))[1] + qty)
    def total(self):
        return round(sum(p * q for p, q in self.items.values()), 2)

def apply_coupon(total, code):
    codes = {"SAVE10": 0.10, "HALF": 0.50}
    if code not in codes:
        raise KeyError(code)
    return round(total * (1 - codes[code]), 2)

class CheckoutTests(unittest.TestCase):
    def test_total_sums_items(self):
        c = Cart(); c.add("a", 2.5, 2); c.add("b", 1.0)
        self.assertEqual(c.total(), 6.0)
    def test_rejects_zero_qty(self):
        with self.assertRaises(ValueError):
            Cart().add("a", 1.0, 0)
    def test_coupon_applies(self):
        self.assertEqual(apply_coupon(100.0, "SAVE10"), 90.0)
    def test_unknown_coupon_fails(self):
        with self.assertRaises(KeyError):
            apply_coupon(10.0, "BOGUS")

if __name__ == "__main__":
    unittest.main()
EOF
